#[derive(Debug, Clone)]
struct Interval {
    min: f64,
    max: f64,
}

impl Interval {
    fn new(min: f64, max: f64) -> Self {
        assert!(min < max, "Interval minimum must be less than maximum");
        Interval { min, max }
    }
}

#[derive(Debug, Clone)]
struct ChebyshevPoly {
    coefficients: Vec<i32>,
    domain: Interval,
    window: Interval,
}

fn chebyshev(coef: Vec<i8>) -> ChebyshevPoly {
    // Input size assumed positive as per problem statement.
    // Convert coefficients from i8 to i32 without changing order.
    let coefficients: Vec<i32> = coef.into_iter().map(|c| c as i32).collect();

    // Set default domain interval [-1, 1] and window interval [-1, 1].
    // Both intervals are valid since -1 < 1.
    let domain = Interval::new(-1.0, 1.0);
    let window = Interval::new(-1.0, 1.0);

    ChebyshevPoly {
        coefficients,
        domain,
        window,
    }
}